// Errors:
//   - [ErrArchMismatch]: [Handle.GemmBatchedEx] is only supported for GPU with architecture capabilities equal to or greater than 5.0.
//   - [ErrExecutionFailed]: The function failed to launch on the GPU.
//   - [ErrInvalidValue]: If m < 0 or n < 0 or k < 0, or if transa and transb are not one of [OpN], [OpC], [OpT], or if lda < max(1, m) when transa == [OpN] and lda < max(1, k) otherwise, or if ldb < max(1, k) when transb == [OpN] and ldb < max(1, n) otherwise, or if ldc < max(1, m), or if alpha or beta are NULL, or if Atype or Btype or Ctype or algo or computeType is not supported
//   - [ErrNotInitialized]: The library was not initialized.
//   - [ErrNotSupported]: The combination of the parameters Atype, Btype and Ctype or the algorithm, algo is not supported.
//
// Wraps cublasGemmBatchedEx.
func gemmBatchedEx(handle Handle, transa Operation, transb Operation, m int32, n int32, k int32, alpha Scalar, aarray driver.DevicePtr, atype DataType, lda int32, barray driver.DevicePtr, btype DataType, ldb int32, beta Scalar, carray driver.DevicePtr, ctype DataType, ldc int32, batchCount int32, computeType ComputeType, algo GemmAlgo) error {
	if err := checkLibSym("cublasGemmBatchedEx"); err != nil {
		return err
	}
	if k := computeTypeKinds(int64(computeType)) & dataTypeDomains(int64(ctype)); !alpha.is(k) {
		return scalarError("cublasGemmBatchedEx", "alpha", alpha, k)
	}
	if k := computeTypeKinds(int64(computeType)) & dataTypeDomains(int64(ctype)); !beta.is(k) {
		return scalarError("cublasGemmBatchedEx", "beta", beta, k)
	}
	_scalars := scalarCells.get()
	defer scalarCells.put(_scalars)
	return toError(fngemmBatchedEx(handle, transa, transb, m, n, k, alpha.arg(&_scalars[0]), uintptr(aarray), atype, lda, uintptr(barray), btype, ldb, beta.arg(&_scalars[1]), uintptr(carray), ctype, ldc, batchCount, computeType, algo), "cublasGemmBatchedEx")
}

